static void setupModels(JavaGameSession& game){game.pendingPackFonts.clear();game.packFontError.clear();game.resourcePackConnection=2;game.resourcePackGeneration=3;game.resourcePacks={JavaGameSession::ResourcePack{}};game.resourcePacks[0].id="practice";strings={{"pack_fonts.id","practice"},{"pack_fonts.textures.0.rgba_base64","/////w=="},{"pack_fonts.models.0.id","oraxen:test"},{"pack_fonts.models.0.tints.0.kind","custom_model_data"},{"pack_fonts.model_errors.0","Unsupported animation"}};arrays={{"pack_fonts.textures",1},{"pack_fonts.fonts",0},{"pack_fonts.models",1},{"pack_fonts.models.0.quads",1},{"pack_fonts.models.0.tints",1},{"pack_fonts.models.0.quads.0.vertices",4},{"pack_fonts.model_errors",1}};numbers={{"pack_fonts.connection",2},{"pack_fonts.generation",3},{"pack_fonts.textures.0.width",1},{"pack_fonts.textures.0.height",1},{"pack_fonts.models.0.quads.0.texture",0},{"pack_fonts.models.0.quads.0.tint",0},{"pack_fonts.models.0.tints.0.color",16777215},{"pack_fonts.models.0.tints.0.index",1},{"pack_fonts.models.0.tints.0.default_color",65280}};for(const char* field:{"rotation","translation","scale"}){std::string p=std::string("pack_fonts.models.0.gui.")+field;arrays[p]=3;for(int i=0;i<3;++i)numbers[p+"."+std::to_string(i)]=std::string(field)=="scale"?1:0;}for(int v=0;v<4;++v){std::string p="pack_fonts.models.0.quads.0.vertices."+std::to_string(v);arrays[p]=5;for(int k=0;k<5;++k)numbers[p+"."+std::to_string(k)]=k<3?16:1;}eventKind=TCPE_JAVA_PACK_FONTS;}
static void applyModels(JavaGameSession& g){pending=true;g.tick();}
static void setupAnimation(JavaGameSession& game){setupModels(game);arrays["pack_fonts.animations"]=1;arrays["pack_fonts.animations.0.frames"]=2;numbers["pack_fonts.animations.0.texture"]=0;numbers["pack_fonts.animations.0.frames.0.time"]=2;numbers["pack_fonts.animations.0.frames.1.time"]=3;booleans["pack_fonts.animations.0.interpolate"]=true;strings["pack_fonts.animations.0.frames.0.rgba_base64"]="/wAA/w==";strings["pack_fonts.animations.0.frames.1.rgba_base64"]="AP8AAA==";}
int main(){JavaGameSession game;setupAnimation(game);applyModels(game);assert(game.pendingPackFonts.size()==1);const auto& animation=game.pendingPackFonts[0].animations[0];assert(animation.texture==0&&animation.interpolate&&animation.frames.size()==2&&animation.frames[0].time==2&&animation.frames[1].time==3);assert(animation.frames[0].rgba[0]==255&&animation.frames[1].rgba[3]==0);
 for(double bad:{0.,-1.,1.5,1000001.,std::numeric_limits<double>::infinity()}){setupAnimation(game);numbers["pack_fonts.animations.0.frames.0.time"]=bad;applyModels(game);assert(game.pendingPackFonts.empty());}
 setupAnimation(game);numbers["pack_fonts.animations.0.texture"]=1;applyModels(game);assert(game.pendingPackFonts.empty());
 setupAnimation(game);arrays["pack_fonts.animations.0.frames"]=1025;applyModels(game);assert(game.pendingPackFonts.empty());
 setupAnimation(game);arrays["pack_fonts.animations.0.frames"]=0;applyModels(game);assert(game.pendingPackFonts.empty());
 setupAnimation(game);strings["pack_fonts.animations.0.frames.0.rgba_base64"]="AAAA";applyModels(game);assert(game.pendingPackFonts.empty());
 setupAnimation(game);arrays["pack_fonts.animations"]=2;arrays["pack_fonts.animations.1.frames"]=1;numbers["pack_fonts.animations.1.texture"]=0;applyModels(game);assert(game.pendingPackFonts.empty());
 setupModels(game);applyModels(game);assert(game.pendingPackFonts.size()==1&&game.pendingPackFonts[0].animations.empty());
 std::cout<<"Animated pack handoff: page/frame byte bounds, exact durations, finite positive dwell, duplicate-page rejection and legacy optional schema PASS\n";
}
